import type { MetadataRoute } from "next";
import { courses } from "@/data/courses";
import { services } from "@/data/services";
import { comparisons } from "@/data/comparisons";
import { articles } from "@/data/articles";

// Canonical base — the REPLICA build itself, not the official domain and
// not Leo's domain. v2 fix: replica v1's sitemap pointed at
// gsitssolutions.com; every URL here is self-referential to the replica.
const base = "https://gradespot-app.vercel.app";

// lastmod per route, from real git history only — generated by
// scripts/sitemap-lastmod.py (ported from Leo's script; Leo DECISIONS
// §25.33). A route's date is the last commit touching its page.tsx
// (static routes) or changing its slug's occurrence count in its data
// file (dynamic routes). These are FILE-TOUCH dates, not a claim that
// the visible content changed on that day. Routes with no history carry
// NO lastmod, never an invented date — so this map starts empty and is
// filled by the script after the v2 pages are committed on this branch.
const LASTMOD: Record<string, string> = {};

export default function sitemap(): MetadataRoute.Sitemap {
  const staticPaths = [
    "",
    "/about-us",
    "/trainings",
    "/services",
    "/resources",
    "/team-members",
    "/team-members/nikhil-duth-d",
    "/why-choose-us",
    "/testimonials",
    "/student-certifications",
    "/certificate-verification",
    "/pricing",
    "/for-institutes",
    "/for-colleges",
    "/career-support",
    "/compare",
    "/blog",
    "/training-institute-in-dilsukhnagar-hyderabad",
    "/contact-us",
    "/faq",
    "/terms-and-conditions",
    "/register",
    "/accessibility",
    "/partner-with-us",
  ];
  return [
    ...staticPaths.map((p) => ({ url: `${base}${p || "/"}`, lastModified: LASTMOD[p || "/"] })),
    ...courses.map((c) => ({ url: `${base}/trainings/${c.slug}`, lastModified: LASTMOD[`/trainings/${c.slug}`] })),
    ...services.map((s) => ({ url: `${base}/services/${s.slug}`, lastModified: LASTMOD[`/services/${s.slug}`] })),
    // v2: city × course landing pages, comparison pairs and articles.
    ...courses
      .filter((c) => !c.catalogOnly)
      .map((c) => ({ url: `${base}/lp/${c.slug}-in-hyderabad`, lastModified: LASTMOD[`/lp/${c.slug}-in-hyderabad`] })),
    ...comparisons.map((c) => ({ url: `${base}/compare/${c.slug}`, lastModified: LASTMOD[`/compare/${c.slug}`] })),
    ...articles.map((a) => ({ url: `${base}/blog/${a.slug}`, lastModified: LASTMOD[`/blog/${a.slug}`] })),
  ];
}
